1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	/**
6	 * The single source of truth for an owner's canonical region, derived from the postcode and city. A
7	 * region is a short code (NSW, VIC, QLD) fixed by two lookup tables: the inclusive 4-digit postcode
8	 * range per region, and the city-to-region fallback used when the postcode yields nothing.
9	 *
10	 * <p>{@link #fromPostcode} answers the region for a postcode alone (or {@code null}) and is the source
11	 * of the REGION component of an owner's {@code customerCode}; {@link #regionOf} reads that component
12	 * back out of a {@code customerCode}, which is how a whole owner resolves to a locality.
13	 */
14	public final class OwnerRegion {
15	
16	    /** City -> canonical region, from the fixed city-to-region table. */
17	    private static final Map<String, String> CITY_REGION = Map.of(
18	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
19	
20	    /** Region -> inclusive 4-digit postcode range {low, high}. */
21	    private static final Map<String, int[]> REGION_RANGE = Map.of(
22	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
23	
24	    private OwnerRegion() {
25	    }
26	
27	    /** The canonical region for {@code city} from the fixed city-to-region table, or {@code null}. */
28	    static String regionForCity(String city) {
29	        return city == null ? null : CITY_REGION.get(city);
30	    }
31	
32	    /** The inclusive 4-digit postcode range {low, high} for {@code region}, or {@code null}. */
33	    static int[] rangeForRegion(String region) {
34	        return REGION_RANGE.get(region);
35	    }
36	
37	    /**
38	     * The region whose fixed range contains {@code postcode} (NSW 2000-2099, VIC 3000-3099,
39	     * QLD 4000-4099), or {@code null} when the postcode is absent, non-numeric, or in no known range.
40	     */
41	    public static String fromPostcode(String postcode) {
42	        if (postcode == null || postcode.isBlank()) {
43	            return null;
44	        }
45	        int value;
46	        try {
47	            value = Integer.parseInt(postcode.trim());
48	        }
49	        catch (NumberFormatException ex) {
50	            return null;
51	        }
52	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
53	            int[] range = entry.getValue();
54	            if (value >= range[0] && value <= range[1]) {
55	                return entry.getKey();
56	            }
57	        }
58	        return null;
59	    }
60	
61	    /**
62	     * The REGION component of a {@code customerCode} ({@code <REGION>-<HASH8>}) — the owner's locality.
63	     * Now that identity is region-and-hash, the locality is read straight off the assigned code rather
64	     * than recomputed, so it always matches the code. {@code UNKNOWN} when the code is absent or has no
65	     * region component.
66	     */
67	    public static String regionOf(String customerCode) {
68	        if (customerCode == null) {
69	            return "UNKNOWN";
70	        }
71	        int dash = customerCode.indexOf('-');
72	        return dash < 0 ? "UNKNOWN" : customerCode.substring(0, dash);
73	    }
74	}
