261	        return new ToStringCreator(this)
262	
263	            .append("id", this.getId())
264	            .append("new", this.isNew())
265	            .append("lastName", this.getLastName())
266	            .append("firstName", this.getFirstName())
267	            .append("address", this.address)
268	            .append("city", this.city)
269	            .append("telephone", this.telephone)
270	            .toString();
271	    }
